/// <summary>
/// MPJ_34596_TransferOrderFinalisation implement the posting of delivery note
/// </summary>
final class MetInventTransferMultiShip extends InventTransferMultiShip
{
}

Method.Source:
/// <summary>
/// initiated buffer for metfiler
/// </summary>
/// <param name = "_inventTransferParmTable">ParmBuffer</param>
public void initParmBuffer(ParmBuffer _inventTransferParmTable)
{
    InventTransferParmTable inventTransferParmTable = _inventTransferParmTable;
    InventTransferParmTable saveInventTransferParmTable;

    saveInventTransferParmTable.data(_inventTransferParmTable);

    super(_inventTransferParmTable);

    inventTransferParmTable.MetFilters = saveInventTransferParmTable.MetFilters;
}

/// <summary>
///  Handled the scenario for MetTransferShipmentTable
/// </summary>
/// <param name = "_common">common</param>
/// <param name = "_inventTransferParmTable">inventTransferParmTable</param>
public void insert(
    Common _common,
    ParmBuffer _inventTransferParmTable
    )
{
    switch (_common.TableId)
    {
        case tableNum(MetTransferShipmentTable):
            this.MetInsert(_common, _inventTransferParmTable);
            break;

        default:
            super(_common, _inventTransferParmTable);
    }
}

/// <summary>
/// metfilters baed on MetTransferShipmentTable
/// </summary>
/// <param name = "_common">common</param>
/// <returns>container</returns>
internal container MetFilters( Common _common    )
{
    MetTransferShipmentTable metShipTable;
    MetShipmentId metShipId;
  

    switch (_common.TableId)
    {
        case tableNum(MetTransferShipmentTable):
            metShipTable = _common;
            metShipId = metShipTable.ShipmentId;
            break;

    }

    return [metShipId];
}

/// <summary>
/// Packed Filterset for record insertion 
/// </summary>
/// <param name = "_filterSet">container</param>
/// <param name = "_MetShipId">MetShipId</param>
/// <returns>container</returns>
private container MetFilterSet(container _filterSet,MetShipmentId _MetShipId)
{
    Set filterSet;

    if (_filterSet != conNull())
    {
        filterSet = Set::create(_filterSet);
    }
    else
    {
        filterSet = new Set(Types::Container);
    }

    filterSet.add([_MetShipId]);

    return filterSet.pack();
}

/// <summary>
/// records that will be inserted 
/// </summary>
/// <param name = "_common">common</param>
/// <param name = "_inventTransferParmTable">inventTransferParmTable</param>
private void MetInsert(Common _common,InventTransferParmTable _inventTransferParmTable)
{
    MetShipmentId metShipId;
    InventTransferTable inventTransferTable;
    MetTransferShipmentLine metTransferShipmentLine;
    InventTransferParmTable inventTransferParmTable;
    int lines;

    [metShipId] = this.MetFilters(_common);

    while select inventTransferTable
        exists join metTransferShipmentLine
        where metTransferShipmentLine.TransferId == inventTransferTable.TransferId
           && (!metShipId || metTransferShipmentLine.ShipmentId == metShipId)
         
    {
        if (!InventTransferParmTable::exist(parmId, inventTransferTable.TransferId))
        {
            _inventTransferParmTable.MetFilters = this.MetFilterSet(conNull(), metShipId);
            _inventTransferParmTable.LineNum += lines;
            this.insert(inventTransferTable, _inventTransferParmTable);

            lines++;
        }
        else
        {
            inventTransferParmTable = InventTransferParmTable::find(parmId, inventTransferTable.TransferId, true);
            inventTransferParmTable.MetFilters = this.MetFilterSet(inventTransferParmTable.MetFilters, metShipId);
            inventTransferParmTable.doUpdate();
        }
    }
}

/// <summary>
/// Construct MetInventTransferMultiShip
/// </summary>
/// <returns>MetInventTransferMultiShip</returns>
internal static server MetInventTransferMultiShip construct()
{
    return new MetInventTransferMultiShip();
}

/// <summary>
/// Main method to execute the posting delivery note for MetTransferShipmentTable & line
/// </summary>
/// <param name = "_args">args</param>
internal static void main( Args _args)
{
    MetInventTransferMultiShip  metInventTransferMultiShip;

    if (_args.parmEnum() == RunChoose::Run)
    {
        metInventTransferMultiShip = MetInventTransferMultiShip::construct();

        switch (_args.dataset())
        {
            case tableNum(MetTransferShipmentTable):
                metInventTransferMultiShip.parmCalledFromWMS(false);
                RunBaseMultiParm::initFromForm(metInventTransferMultiShip, _args);
                break;

            default:
                RunBaseMultiParm::initParm(metInventTransferMultiShip);
                metInventTransferMultiShip.parmCalledFromWMS(false);
                break;
        }

        if (!metInventTransferMultiShip.prompt())
        {
            return;
        }

        metInventTransferMultiShip.runOperation();
    }
    else
    {
        RunBaseMultiParm::runSpecial(_args);
    }
}
